"use client";

import { useState, useCallback } from "react";
import axios from "axios";
import type {
  ReadProductAttributesDto,
  ReadProductAttributeValueDto,
} from "../types";

export function useAttributes() {
  const [attributes, setAttributes] = useState<ReadProductAttributesDto[]>([]);
  const [loadingAttributes, setLoadingAttributes] = useState(false);
  const [attributesError, setAttributesError] = useState<string | null>(null);
  const [openAttributeId, setOpenAttributeId] = useState<number | null>(null);
  const [attributeSelections, setAttributeSelections] = useState<
    Record<number, number[]>
  >({});
  const [attributeCustomDrafts, setAttributeCustomDrafts] = useState<
    Record<number, string>
  >({});

  const loadAttributes = useCallback(async (categoryId: number) => {
    try {
      setLoadingAttributes(true);
      const res = await axios.get<ReadProductAttributesDto[]>(
        `/api/category/${categoryId}/attributes`,
      );
      setAttributes(res.data ?? []);
      setAttributesError(null);
    } catch (error) {
      console.error("Failed to load category attributes", error);
      setAttributes([]);
      setAttributesError(
        "Không tải được thuộc tính cho ngành hàng đã chọn. Vui lòng thử lại sau.",
      );
    } finally {
      setLoadingAttributes(false);
    }
  }, []);

  const addCustomAttributeValue = useCallback(
    (attrId: number, draft: string, tempId: number) => {
      const newVal: ReadProductAttributeValueDto = { id: tempId, value: draft };
      setAttributes((prev) =>
        prev.map((a) =>
          a.id === attrId
            ? { ...a, values: [...(a.values ?? []), newVal] }
            : a,
        ),
      );
      setAttributeSelections((prev) => {
        const current = prev[attrId] ?? [];
        return { ...prev, [attrId]: [...current, tempId] };
      });
      setAttributeCustomDrafts((prev) => ({ ...prev, [attrId]: "" }));
    },
    [],
  );

  return {
    attributes,
    setAttributes,
    loadingAttributes,
    attributesError,
    openAttributeId,
    setOpenAttributeId,
    attributeSelections,
    setAttributeSelections,
    attributeCustomDrafts,
    setAttributeCustomDrafts,
    loadAttributes,
    addCustomAttributeValue,
  };
}

